draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // trees
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    let x = (i * W / 10) + (Math.sin(t + i) * W / 20);
    let y = H / 2;
    ctx.moveTo(x, y);
    ctx.lineTo(x, y - 50);
  }
  ctx.stroke();

  // path
  ctx.beginPath();
  ctx.moveTo(0, H / 2 + 25);
  ctx.lineTo(W, H / 2 + 25);
  ctx.stroke();

  // rocks
  ctx.fillStyle = 'black';
  for (let i = 0; i < 5; i++) {
    let x = (i * W / 5) + (Math.sin(t + i * 2) * W / 10);
    let y = H / 2 + 20;
    ctx.beginPath();
    ctx.arc(x, y, 10, 0, 2 * Math.PI);
    ctx.fill();
  }

  ctx.restore();
}
